PAIRS = {")": "(", "]": "[", "}": "{"}

def balanced(s):
    stack = []
    for ch in s:
        if ch in "([{":
            stack.append(ch)
        elif ch in ")]}":
            if not stack or stack[-1] != PAIRS[ch]:
                return False
            stack.pop()
    return len(stack) == 0

for s in ["(a[b]{c})", "(]", "((", "{[()()]}", ")("]:
    print(f"{s:10} -> {balanced(s)}")

