public static void insertionSort(int[] a) {
  if (a == null || a.length < 2) return;      // Project 1 guard
  for (int j = 1; j < a.length; j++) {
    int key = a[j];
    int i = j - 1;
    while (i >= 0 && a[i] > key) {
      a[i + 1] = a[i];      // shift the bigger element right
      i = i - 1;
    }
    a[i + 1] = key;         // drop key into the hole
  }
}

